请对以下 case 进行三维加权评分。

=== case_id ===
Case-01-low-power-009

=== 用户原始指令 (query.txt) ===
帮我做个文字压在图上的那种 点一下能跳出去 再从日历读一下我今天有啥事

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "帮我做个文字压在图上的那种 点一下能跳出去 再从日历读一下我今天有啥事",
  "size": "2x2",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "com.huawei.hmos.settings",
        "abilityName": "com.huawei.hmos.settings.MainAbility",
        "uri": "battery"
      }
    }
  ],
  "dataModel": {
    "value": {
      "power": {
        "title": "低电模式",
        "actionText": "电池设置"
      },
      "data": {
        "calendar": {
          "items": [
            {
              "entityName": "calendar_event",
              "entityId": "mock-today-001",
              "title": "项目同步",
              "dtStart": "10:00",
              "dtEnd": "10:30",
              "eventLocation": "线上会议"
            }
          ]
        }
      },
      "state": {
        "loading": false
      }
    }
  },
  "assetCandidates": [
    {
      "assetRef": "save_power_icon",
      "src": "resources/base/media/icon_save_power.png",
      "use": "low power visual icon",
      "description": "低电/省电场景的省电图标，适合作为深色舞台上的背景视觉锚点。",
      "static": true
    }
  ]
}

